SET price = 15.75
WHERE item_name = 'Chicken Caesar Salad';

SELECT o.order_id, o.order_date, SUM(oi.quantity * mi.price) AS calculated_total
FROM Orders o
JOIN OrderItems oi ON o.order_id = oi.order_id
JOIN MenuItems mi ON oi.item_id = mi.item_id
GROUP BY o.order_id, o.order_date;

SELECT mi.category, COUNT(oi.order_item_id) AS total_items_sold
FROM MenuItems mi
JOIN OrderItems oi ON mi.item_id = oi.item_id
GROUP BY mi.category
ORDER BY total_items_sold DESC;

